      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // --- Fix BUG (#1): Bounce logic ---
      const ball = state.ball;

      // Find the distance to each edge
      const distLeft = ball.x + ball.r - brick.x;
      const distRight = brick.x + brick.w - (ball.x - ball.r);
      const distTop = ball.y + ball.r - brick.y;
      const distBottom = brick.y + brick.h - (ball.y - ball.r);

      const minDist = Math.min(distLeft, distRight, distTop, distBottom);

      if (minDist === distLeft) {
        ball.vx = Math.abs(ball.vx);
        ball.x = brick.x - ball.r;
      } else if (minDist === distRight) {
